import sqlite3
conn=sqlite3.connect(':memory:')
conn.row_factory=sqlite3.Row
conn.executescript("""CREATE TABLE hydration_queue(store TEXT,url TEXT,state TEXT,priority INTEGER DEFAULT 100,attempts INTEGER DEFAULT 0,available_at REAL DEFAULT 0,leased_until REAL,lease_token TEXT,first_seen_at REAL,last_started_at REAL,last_finished_at REAL,last_error TEXT,last_http_status INTEGER,PRIMARY KEY(store,url)); CREATE TABLE store_products(store TEXT,url TEXT,price REAL,fetched_at REAL,fetch_status TEXT,PRIMARY KEY(store,url));""")
sql="INSERT INTO hydration_queue(\n                           store,url,state,attempts,available_at,first_seen_at)\n                       VALUES(?,?,?,?,?,?)\n                       ON CONFLICT(store,url) DO UPDATE SET\n                           state=CASE\n                               WHEN hydration_queue.state='PROCESSING'\n                                    AND hydration_queue.leased_until > ?\n                               THEN 'PROCESSING'\n                               WHEN hydration_queue.state='DEAD'\n                               THEN 'DEAD'\n                               WHEN EXISTS (\n                                   SELECT 1 FROM store_products p\n                                    WHERE p.store='deloox'\n                                      AND p.url=hydration_queue.url\n                                      AND p.fetch_status='OK'\n                                      AND p.fetched_at IS NOT NULL\n                                      AND (\n                                          (p.price IS NOT NULL AND p.price > 0\n                                           AND p.fetched_at > ?)\n                                          OR\n                                          ((p.price IS NULL OR p.price <= 0)\n                                           AND p.fetched_at > ?)\n                                      )\n                               ) THEN 'DONE'\n                               ELSE 'PENDING'\n                           END,\n                           available_at=CASE\n                               WHEN hydration_queue.state='PROCESSING'\n                                    AND hydration_queue.leased_until > ?\n                               THEN hydration_queue.available_at\n                               WHEN EXISTS (\n                                   SELECT 1 FROM store_products p\n                                    WHERE p.store='deloox'\n                                      AND p.url=hydration_queue.url\n                                      AND p.fetch_status='OK'\n                                      AND p.fetched_at IS NOT NULL\n                                      AND (\n                                          (p.price IS NOT NULL AND p.price > 0\n                                           AND p.fetched_at > ?)\n                                          OR\n                                          ((p.price IS NULL OR p.price <= 0)\n                                           AND p.fetched_at > ?)\n                                      )\n                               ) THEN hydration_queue.available_at\n                               WHEN hydration_queue.state IN ('ERROR','DEAD')\n                               THEN excluded.available_at\n                               ELSE MIN(hydration_queue.available_at, excluded.available_at)\n                           END,\n                           priority=CASE\n                               WHEN EXISTS (\n                                   SELECT 1 FROM store_products p\n                                    WHERE p.store='deloox'\n                                      AND p.url=hydration_queue.url\n                                      AND p.fetch_status='OK'\n                                      AND p.fetched_at IS NOT NULL\n                                      AND (\n                                          (p.price IS NOT NULL AND p.price > 0\n                                           AND p.fetched_at > ?)\n                                          OR\n                                          ((p.price IS NULL OR p.price <= 0)\n                                           AND p.fetched_at > ?)\n                                      )\n                               ) THEN hydration_queue.priority\n                               ELSE MIN(hydration_queue.priority, 100)\n                           END,\n                           last_error=CASE\n                               WHEN EXISTS (\n                                   SELECT 1 FROM store_products p\n                                    WHERE p.store='deloox'\n                                      AND p.url=hydration_queue.url\n                                      AND p.fetch_status='OK'\n                                      AND p.fetched_at IS NOT NULL\n                                      AND (\n                                          (p.price IS NOT NULL AND p.price > 0\n                                           AND p.fetched_at > ?)\n                                          OR\n                                          ((p.price IS NULL OR p.price <= 0)\n                                           AND p.fetched_at > ?)\n                                      )\n                               ) THEN hydration_queue.last_error\n                               ELSE NULL\n                           END"
params=('deloox', url, 'PENDING', 0, 200000, 200000, 200000, 200000 - 24 * 60 * 60, 200000 - 6 * 60 * 60, 200000, 200000 - 24 * 60 * 60, 200000 - 6 * 60 * 60, 200000 - 24 * 60 * 60, 200000 - 6 * 60 * 60, 200000 - 24 * 60 * 60, 200000 - 6 * 60 * 60)
assert sql.count('?')==len(params),(sql.count('?'),len(params))
def run(fetched,price=34.99,old_state='DONE'):
 conn.execute("DELETE FROM hydration_queue")
 conn.execute("INSERT INTO hydration_queue(store,url,state,attempts,available_at,first_seen_at) VALUES('deloox','u',?,1,1,1)",(old_state,))
 conn.execute("INSERT OR REPLACE INTO store_products VALUES('deloox','u',?,?, 'OK')",(price,fetched))
 conn.execute(sql,params)
 return conn.execute("SELECT state,available_at FROM hydration_queue WHERE url='u'").fetchone()
assert run(100)['state']=='PENDING'
assert run(199000)['state']=='DONE'
assert run(100,price=None)['state']=='PENDING'
assert run(199500,price=None)['state']=='DONE'
conn.execute("DELETE FROM hydration_queue")
conn.execute("INSERT INTO hydration_queue(store,url,state,attempts,available_at,first_seen_at) VALUES('deloox','u','PROCESSING',1,10,1)")
conn.execute("UPDATE hydration_queue SET leased_until=999999 WHERE url='u'")
conn.execute(sql,params)
assert conn.execute("SELECT state FROM hydration_queue WHERE url='u'").fetchone()[0]=='PROCESSING'
conn.execute("UPDATE hydration_queue SET state='DEAD',leased_until=NULL WHERE url='u'")
conn.execute(sql,params)
assert conn.execute("SELECT state FROM hydration_queue WHERE url='u'").fetchone()[0]=='DEAD'
print('Deloox upsert SQLite checks: stale, fresh, missing-price cooldown, live lease, DEAD all pass')
